--
-- Name: cancel_reservations_on_block(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.cancel_reservations_on_block() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
BEGIN
    IF NEW.status = 'Blocked' AND OLD.status IS DISTINCT FROM 'Blocked' THEN
        UPDATE reservations
        SET status = 'Cancelled'
        WHERE reader_id = NEW.reader_id
          AND status = 'Active';
    END IF;
    RETURN NEW;
END;
$$;


