--

CREATE FUNCTION public.comprehensive_audit_log() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
    v_id INTEGER;
    v_key TEXT;
    v_old JSONB;
    v_new JSONB;
BEGIN
    v_key := CASE TG_TABLE_NAME
        WHEN 'readers' THEN 'reader_id'
        WHEN 'loans' THEN 'loan_id'
        ELSE 'book_id'
    END;
    IF TG_OP = 'DELETE' THEN
        v_old := to_jsonb(OLD);
        v_id := (v_old ->> v_key)::INTEGER;
        VALUES (TG_TABLE_NAME, TG_OP, v_id, v_old, NULL);
        RETURN OLD;
    END IF;

    v_new := to_jsonb(NEW);
    v_id := (v_new ->> v_key)::INTEGER;
    IF TG_OP = 'UPDATE' THEN
        v_old := to_jsonb(OLD);
    END IF;
    VALUES (TG_TABLE_NAME, TG_OP, v_id, v_old, v_new);
    RETURN NEW;
END;
$$;


--
-- Name: create_backup_point(character varying, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.create_backup_point(p_name character varying, p_description text DEFAULT NULL::text) RETURNS integer
    LANGUAGE plpgsql
    AS $$
DECLARE
    v_backup_id INTEGER;
    v_snapshot JSONB;
BEGIN
    SELECT jsonb_build_object(
        'genres', COALESCE((SELECT jsonb_agg(to_jsonb(g)) FROM genres g), '[]'::jsonb),
        'publishers', COALESCE((SELECT jsonb_agg(to_jsonb(p)) FROM publishers p), '[]'::jsonb),
        'authors', COALESCE((SELECT jsonb_agg(to_jsonb(a)) FROM authors a), '[]'::jsonb),
        'books', COALESCE((SELECT jsonb_agg(to_jsonb(b)) FROM books b), '[]'::jsonb),
        'readers', COALESCE((SELECT jsonb_agg(to_jsonb(r)) FROM readers r), '[]'::jsonb),
        'loans', COALESCE((SELECT jsonb_agg(to_jsonb(l)) FROM loans l), '[]'::jsonb),
        'reservations', COALESCE((SELECT jsonb_agg(to_jsonb(rv)) FROM reservations rv), '[]'::jsonb)
    ) INTO v_snapshot;

    VALUES (p_name, p_description, v_snapshot)
    RETURNING backup_id INTO v_backup_id;
    RETURN v_backup_id;
END;
$$;


--
-- Name: create_book_version(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.create_book_version() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
    v_version_number INTEGER;
BEGIN
    UPDATE books_versions
    SET valid_to = CURRENT_TIMESTAMP
    WHERE book_id = NEW.book_id AND valid_to IS NULL;

    SELECT COALESCE(MAX(version_number), 0) + 1
    INTO v_version_number
    FROM books_versions
    WHERE book_id = NEW.book_id;

    VALUES (NEW.book_id, v_version_number, to_jsonb(NEW));
    RETURN NEW;
END;
$$;


--
-- Name: execute_scheduled_operations(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.execute_scheduled_operations() RETURNS integer
    LANGUAGE plpgsql
    AS $$
DECLARE
    v_operation RECORD;
    v_count INTEGER := 0;
BEGIN
    FOR v_operation IN
        SELECT * FROM scheduled_operations
        WHERE status = 'Pending' AND scheduled_for <= CURRENT_TIMESTAMP
        ORDER BY scheduled_for, operation_id
        FOR UPDATE
    LOOP
        BEGIN
            CASE v_operation.operation_type
                WHEN 'UPDATE_BOOK_STATUS' THEN
                    UPDATE books
                    SET available_copies = (v_operation.operation_data->>'available_copies')::INTEGER,
                        updated_at = CURRENT_TIMESTAMP
                    WHERE book_id = (v_operation.operation_data->>'book_id')::INTEGER;
                WHEN 'EXPIRE_RESERVATION' THEN
                    UPDATE reservations
                    SET status = 'Expired'
                    WHERE reservation_id = (v_operation.operation_data->>'reservation_id')::INTEGER
                      AND status = 'Active';
                WHEN 'BLOCK_READER' THEN
                    UPDATE readers
                    SET status = 'Blocked'
                    WHERE reader_id = (v_operation.operation_data->>'reader_id')::INTEGER;
                ELSE
                    RAISE EXCEPTION 'Невідомий тип операції: %', v_operation.operation_type;
            END CASE;

            UPDATE scheduled_operations
            SET status = 'Executed', executed_at = CURRENT_TIMESTAMP, error_message = NULL
            WHERE operation_id = v_operation.operation_id;
            v_count := v_count + 1;
        EXCEPTION WHEN OTHERS THEN
            UPDATE scheduled_operations
            SET status = 'Failed',
                executed_at = CURRENT_TIMESTAMP,
                error_message = SQLERRM
            WHERE operation_id = v_operation.operation_id;
        END;
    END LOOP;
    RETURN v_count;
END;
$$;


--
-- Name: extend_loan(integer, integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.extend_loan(p_loan_id integer, p_days integer DEFAULT 7) RETURNS TABLE(success boolean, message text, new_due_date date)
    LANGUAGE plpgsql
    AS $$
DECLARE
    v_reader_id INTEGER;
    v_status VARCHAR(20);
    v_due DATE;
    v_overdue INTEGER;
BEGIN
    SELECT l.reader_id, r.status, l.due_date
    INTO v_reader_id, v_status, v_due
    FROM loans l
    JOIN readers r ON r.reader_id = l.reader_id
    WHERE l.loan_id = p_loan_id AND l.return_date IS NULL
    FOR UPDATE OF l;

    IF NOT FOUND THEN
        RETURN QUERY SELECT FALSE, 'Відкриту видачу не знайдено'::TEXT, NULL::DATE;
        RETURN;
    END IF;
    IF v_status = 'Blocked' THEN
        RETURN QUERY SELECT FALSE, 'Читач заблокований'::TEXT, NULL::DATE;
        RETURN;
    END IF;

    SELECT COUNT(*) INTO v_overdue
    FROM loans
    WHERE reader_id = v_reader_id
      AND return_date IS NULL
      AND due_date < CURRENT_DATE;

    IF v_overdue > 0 THEN
        RETURN QUERY SELECT FALSE, 'У читача є прострочені книги'::TEXT, NULL::DATE;
        RETURN;
    END IF;

    UPDATE loans
    SET due_date = due_date + p_days
    WHERE loan_id = p_loan_id
    RETURNING due_date INTO v_due;

    RETURN QUERY SELECT TRUE, 'Термін продовжено'::TEXT, v_due;
END;
$$;


--
-- Name: get_book_version(integer, timestamp without time zone); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.get_book_version(p_book_id integer, p_date timestamp without time zone) RETURNS jsonb
    LANGUAGE plpgsql
    AS $$
BEGIN
    RETURN (
        SELECT data
        FROM books_versions
        WHERE book_id = p_book_id
          AND valid_from <= p_date
          AND (valid_to IS NULL OR valid_to > p_date)
        ORDER BY version_number DESC
        LIMIT 1
    );
END;
$$;


--
-- Name: get_changes_report(timestamp without time zone, timestamp without time zone); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.get_changes_report(p_start_date timestamp without time zone, p_end_date timestamp without time zone DEFAULT CURRENT_TIMESTAMP) RETURNS TABLE(change_date date, total_changes bigint, inserts bigint, updates bigint, deletes bigint)
    LANGUAGE plpgsql
    AS $$
BEGIN
    RETURN QUERY
    SELECT
        DATE(changed_at) AS change_date,
        COUNT(*) AS total_changes,
        COUNT(*) FILTER (WHERE operation = 'INSERT') AS inserts,
        COUNT(*) FILTER (WHERE operation = 'UPDATE') AS updates,
        COUNT(*) FILTER (WHERE operation = 'DELETE') AS deletes
    FROM audit_log
    WHERE changed_at BETWEEN p_start_date AND p_end_date
    GROUP BY DATE(changed_at)
    ORDER BY change_date DESC;
END;
$$;


--
-- Name: issue_loan(integer, integer, integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.issue_loan(p_book_id integer, p_reader_id integer, p_days integer DEFAULT 14) RETURNS TABLE(success boolean, message text, loan_id integer)
    LANGUAGE plpgsql
    AS $$
DECLARE
    v_status VARCHAR(20);
    v_available INTEGER;
    v_loan_id INTEGER;
BEGIN
    IF p_days < 1 OR p_days > 60 THEN
        RETURN QUERY SELECT FALSE, 'Термін видачі має бути від 1 до 60 днів'::TEXT, NULL::INTEGER;
        RETURN;
    END IF;

    SELECT status INTO v_status FROM readers WHERE reader_id = p_reader_id FOR UPDATE;
    IF NOT FOUND THEN
        RETURN QUERY SELECT FALSE, 'Читача не знайдено'::TEXT, NULL::INTEGER;
        RETURN;
    END IF;
    IF v_status <> 'Active' THEN
        RETURN QUERY SELECT FALSE, 'Читач не має статусу Active'::TEXT, NULL::INTEGER;
        RETURN;
    END IF;

    SELECT available_copies INTO v_available
    FROM books WHERE book_id = p_book_id FOR UPDATE;
    IF NOT FOUND THEN
        RETURN QUERY SELECT FALSE, 'Книгу не знайдено'::TEXT, NULL::INTEGER;
        RETURN;
    END IF;
    IF v_available <= 0 THEN
        RETURN QUERY SELECT FALSE, 'Немає вільних примірників'::TEXT, NULL::INTEGER;
        RETURN;
    END IF;

    VALUES (p_book_id, p_reader_id, CURRENT_DATE, CURRENT_DATE + p_days)
    RETURNING loans.loan_id INTO v_loan_id;

    UPDATE books
    SET available_copies = available_copies - 1,
        updated_at = CURRENT_TIMESTAMP
    WHERE book_id = p_book_id;

    RETURN QUERY SELECT TRUE, 'Книгу видано'::TEXT, v_loan_id;
END;
$$;


