--
-- Name: maintain_database(); Type: PROCEDURE; Schema: public; Owner: -
--

CREATE PROCEDURE public.maintain_database()
    LANGUAGE plpgsql
    AS $$
DECLARE
    tbl RECORD;
    v_count INTEGER := 0;
BEGIN
    ANALYZE;
    COMMIT;
    FOR tbl IN
        SELECT tablename
        FROM pg_tables
        WHERE schemaname = 'public'
        ORDER BY tablename
    LOOP
        EXECUTE format('REINDEX TABLE public.%I', tbl.tablename);
        v_count := v_count + 1;
        COMMIT;
    END LOOP;
    VALUES ('ANALYZE + REINDEX', 'tables=' || v_count);
END;
$$;


