--
-- Name: restore_from_backup(integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.restore_from_backup(p_backup_id integer) RETURNS boolean
    LANGUAGE plpgsql
    AS $$
DECLARE
    v_snapshot JSONB;
    r RECORD;
BEGIN
    SELECT data_snapshot INTO v_snapshot
    FROM backup_points
    WHERE backup_id = p_backup_id;

    IF v_snapshot IS NULL THEN
        RAISE EXCEPTION 'Контрольну точку % не знайдено', p_backup_id;
    END IF;

    FOR r IN
        SELECT c.relname AS table_name, t.tgname
        FROM pg_trigger t
        JOIN pg_class c ON c.oid = t.tgrelid
        JOIN pg_namespace n ON n.oid = c.relnamespace
        WHERE n.nspname = 'public'
          AND NOT t.tgisinternal
          AND c.relname IN ('books', 'loans', 'readers', 'reservations', 'authors')
    LOOP
        EXECUTE format('ALTER TABLE %I DISABLE TRIGGER %I', r.table_name, r.tgname);
    END LOOP;

    TRUNCATE TABLE loans, reservations, books, readers, authors, publishers, genres RESTART IDENTITY CASCADE;


    PERFORM setval(pg_get_serial_sequence('genres', 'genre_id'), GREATEST((SELECT COALESCE(MAX(genre_id), 1) FROM genres), 1));
    PERFORM setval(pg_get_serial_sequence('publishers', 'publisher_id'), GREATEST((SELECT COALESCE(MAX(publisher_id), 1) FROM publishers), 1));
    PERFORM setval(pg_get_serial_sequence('authors', 'author_id'), GREATEST((SELECT COALESCE(MAX(author_id), 1) FROM authors), 1));
    PERFORM setval(pg_get_serial_sequence('readers', 'reader_id'), GREATEST((SELECT COALESCE(MAX(reader_id), 1) FROM readers), 1));
    PERFORM setval(pg_get_serial_sequence('books', 'book_id'), GREATEST((SELECT COALESCE(MAX(book_id), 1) FROM books), 1));
    PERFORM setval(pg_get_serial_sequence('loans', 'loan_id'), GREATEST((SELECT COALESCE(MAX(loan_id), 1) FROM loans), 1));
    PERFORM setval(pg_get_serial_sequence('reservations', 'reservation_id'), GREATEST((SELECT COALESCE(MAX(reservation_id), 1) FROM reservations), 1));

    FOR r IN
        SELECT c.relname AS table_name, t.tgname
        FROM pg_trigger t
        JOIN pg_class c ON c.oid = t.tgrelid
        JOIN pg_namespace n ON n.oid = c.relnamespace
        WHERE n.nspname = 'public'
          AND NOT t.tgisinternal
          AND c.relname IN ('books', 'loans', 'readers', 'reservations', 'authors')
    LOOP
        EXECUTE format('ALTER TABLE %I ENABLE TRIGGER %I', r.table_name, r.tgname);
    END LOOP;

    RETURN TRUE;
END;
$$;


--
-- Name: return_loan(integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.return_loan(p_loan_id integer) RETURNS TABLE(success boolean, message text)
    LANGUAGE plpgsql
    AS $$
DECLARE
    v_book_id INTEGER;
BEGIN
    SELECT book_id INTO v_book_id
    FROM loans
    WHERE loan_id = p_loan_id AND return_date IS NULL
    FOR UPDATE;

    IF NOT FOUND THEN
        RETURN QUERY SELECT FALSE, 'Відкриту видачу не знайдено'::TEXT;
        RETURN;
    END IF;

    UPDATE loans SET return_date = CURRENT_DATE WHERE loan_id = p_loan_id;

    UPDATE books
    SET available_copies = LEAST(total_copies, available_copies + 1),
        updated_at = CURRENT_TIMESTAMP
    WHERE book_id = v_book_id;

    RETURN QUERY SELECT TRUE, 'Книгу повернено'::TEXT;
END;
$$;


--
-- Name: revert_book_to_version(integer, integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.revert_book_to_version(p_book_id integer, p_version integer) RETURNS text
    LANGUAGE plpgsql
    AS $$
DECLARE
    v_data JSONB;
    v_title TEXT;
BEGIN
    SELECT data INTO v_data
    FROM books_versions
    WHERE book_id = p_book_id AND version_number = p_version;

    IF v_data IS NULL THEN
        RAISE EXCEPTION 'Версію % книги % не знайдено', p_version, p_book_id;
    END IF;

    UPDATE books
    SET title = v_data->>'title',
        pages = (v_data->>'pages')::INTEGER,
        publication_year = (v_data->>'publication_year')::INTEGER,
        genre_id = NULLIF(v_data->>'genre_id', '')::INTEGER,
        publisher_id = NULLIF(v_data->>'publisher_id', '')::INTEGER,
        updated_at = CURRENT_TIMESTAMP
    WHERE book_id = p_book_id
    RETURNING title INTO v_title;

    RETURN 'Відновлено описові поля до версії ' || p_version || ': ' || v_title;
END;
$$;


