--
-- Name: validate_reader_contact(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.validate_reader_contact() RETURNS trigger
    LANGUAGE plpgsql
    AS $_$
BEGIN
    IF NEW.email !~* '^[A-Za-z0-9._%+-]+@[A-Za-z0-9.-]+\.[A-Za-z]{2,}$' THEN
        RAISE EXCEPTION 'Некоректний email: %', NEW.email;
    END IF;
    IF NEW.phone IS NOT NULL AND NEW.phone !~ '^\+380[0-9]{9}$' THEN
        RAISE EXCEPTION 'Некоректний телефон (очікується +380 і 9 цифр): %', NEW.phone;
    END IF;
    RETURN NEW;
END;
$_$;


