CREATE TABLE public.books (
    book_id integer NOT NULL,
    isbn character varying(17) NOT NULL,
    title character varying(200) NOT NULL,
    author_id integer NOT NULL,
    publisher_id integer,
    genre_id integer,
    publication_year integer NOT NULL,
    pages integer,
    total_copies integer DEFAULT 1 NOT NULL,
    available_copies integer DEFAULT 1 NOT NULL,
    created_at timestamp without time zone DEFAULT CURRENT_TIMESTAMP NOT NULL,
    updated_at timestamp without time zone DEFAULT CURRENT_TIMESTAMP NOT NULL,
    CONSTRAINT books_available_copies_check CHECK ((available_copies >= 0)),
    CONSTRAINT books_check CHECK ((available_copies <= total_copies)),
    CONSTRAINT books_pages_check CHECK (((pages > 0) AND (pages <= 10000))),
    CONSTRAINT books_publication_year_check CHECK (((publication_year >= 1450) AND ((publication_year)::numeric <= EXTRACT(year FROM CURRENT_DATE)))),
    CONSTRAINT books_total_copies_check CHECK ((total_copies >= 0))
);


