-- Name: mv_genre_summary; Type: MATERIALIZED VIEW; Schema: public; Owner: -
--

CREATE MATERIALIZED VIEW public.mv_genre_summary AS
 SELECT g.genre_id,
    g.name AS genre,
    count(b.book_id) AS books_count,
    COALESCE(sum(b.total_copies), (0)::bigint) AS total_copies,
    COALESCE(sum(b.available_copies), (0)::bigint) AS available_copies
   FROM (public.genres g
     LEFT JOIN public.books b ON ((b.genre_id = g.genre_id)))
  GROUP BY g.genre_id, g.name
  WITH NO DATA;


