--
-- Name: v_active_loans; Type: VIEW; Schema: public; Owner: -
--

CREATE VIEW public.v_active_loans AS
 SELECT l.loan_id,
    l.loan_date,
    l.due_date,
    l.return_date,
    b.book_id,
    b.title,
    r.reader_id,
    (((r.first_name)::text || ' '::text) || (r.last_name)::text) AS reader_name,
    r.library_card_number,
    ((l.return_date IS NULL) AND (l.due_date < CURRENT_DATE)) AS is_overdue
   FROM ((public.loans l
     JOIN public.books b ON ((b.book_id = l.book_id)))
     JOIN public.readers r ON ((r.reader_id = l.reader_id)))
  WHERE (l.return_date IS NULL);


--
-- Name: v_book_versions; Type: VIEW; Schema: public; Owner: -
--

CREATE VIEW public.v_book_versions AS
 SELECT v.book_id,
    b.title AS current_title,
    v.version_number,
    (v.data ->> 'title'::text) AS version_title,
    (v.data ->> 'pages'::text) AS version_pages,
    v.valid_from,
    v.valid_to,
    v.created_by,
    (v.valid_to IS NULL) AS is_current
   FROM (public.books_versions v
     JOIN public.books b ON ((b.book_id = v.book_id)));


--
-- Name: v_books_catalog; Type: VIEW; Schema: public; Owner: -
--

CREATE VIEW public.v_books_catalog AS
 SELECT b.book_id,
    b.isbn,
    b.title,
    b.publication_year,
    b.pages,
    b.total_copies,
    b.available_copies,
    a.author_id,
    (((a.first_name)::text || ' '::text) || (a.last_name)::text) AS author_name,
    a.country AS author_country,
    p.publisher_id,
    p.name AS publisher_name,
    g.genre_id,
    g.name AS genre_name
   FROM (((public.books b
     JOIN public.authors a ON ((a.author_id = b.author_id)))
     LEFT JOIN public.publishers p ON ((p.publisher_id = b.publisher_id)))
     LEFT JOIN public.genres g ON ((g.genre_id = b.genre_id)));


--
-- Name: v_books_change_history; Type: VIEW; Schema: public; Owner: -
--

CREATE VIEW public.v_books_change_history AS
 SELECT log_id,
    operation,
    record_id AS book_id,
    COALESCE((new_data ->> 'title'::text), (old_data ->> 'title'::text)) AS title,
        CASE
            WHEN ((operation)::text = 'INSERT'::text) THEN 'Додано нову книгу'::text
            WHEN ((operation)::text = 'DELETE'::text) THEN 'Видалено книгу'::text
            WHEN ((old_data ->> 'available_copies'::text) IS DISTINCT FROM (new_data ->> 'available_copies'::text)) THEN ((('Доступні примірники: '::text || COALESCE((old_data ->> 'available_copies'::text), '?'::text)) || ' → '::text) || COALESCE((new_data ->> 'available_copies'::text), '?'::text))
            WHEN ((old_data ->> 'title'::text) IS DISTINCT FROM (new_data ->> 'title'::text)) THEN ((('Назва: '::text || COALESCE((old_data ->> 'title'::text), ''::text)) || ' → '::text) || COALESCE((new_data ->> 'title'::text), ''::text))
            WHEN ((old_data ->> 'pages'::text) IS DISTINCT FROM (new_data ->> 'pages'::text)) THEN ((('Сторінки: '::text || COALESCE((old_data ->> 'pages'::text), ''::text)) || ' → '::text) || COALESCE((new_data ->> 'pages'::text), ''::text))
            ELSE 'Оновлено інші поля'::text
        END AS change_description,
    changed_at,
    changed_by
   FROM public.audit_log a
  WHERE ((table_name)::text = 'books'::text);


--
-- Name: v_overdue_loans; Type: VIEW; Schema: public; Owner: -
--

CREATE VIEW public.v_overdue_loans AS
 SELECT loan_id,
    book_id,
    title,
    reader_id,
    reader_name,
    library_card_number,
    loan_date,
    due_date,
    (CURRENT_DATE - due_date) AS days_overdue
   FROM public.v_active_loans
  WHERE is_overdue;


--
-- Name: v_reader_contacts; Type: VIEW; Schema: public; Owner: -
--

CREATE VIEW public.v_reader_contacts AS
 SELECT reader_id,
    first_name,
    last_name,
    email,
    phone,
    status
   FROM public.readers
  WHERE ((status)::text <> 'Inactive'::text);


--
-- Name: v_reader_loan_stats; Type: VIEW; Schema: public; Owner: -
--

CREATE VIEW public.v_reader_loan_stats AS
 SELECT r.reader_id,
    (((r.first_name)::text || ' '::text) || (r.last_name)::text) AS reader_name,
    r.status,
    count(l.loan_id) AS loans_total,
    count(l.loan_id) FILTER (WHERE (l.return_date IS NULL)) AS open_loans,
    count(l.loan_id) FILTER (WHERE ((l.return_date IS NULL) AND (l.due_date < CURRENT_DATE))) AS overdue_loans
   FROM (public.readers r
     LEFT JOIN public.loans l ON ((l.reader_id = r.reader_id)))
  GROUP BY r.reader_id, r.first_name, r.last_name, r.status;


