-- Name: v_reader_contacts v_reader_contacts_update; Type: RULE; Schema: public; Owner: -
--

CREATE RULE v_reader_contacts_update AS
    ON UPDATE TO public.v_reader_contacts DO INSTEAD  UPDATE public.readers SET email = new.email, phone = new.phone, status = new.status
  WHERE (readers.reader_id = old.reader_id);


